"""Local gallery of original native Android captures; no visual pass inference."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'Verification/Evidence/DailyGift'
def run():
    manifest=json.loads((OUT/'Player_Source_SHA256.json').read_text());sections=[]
    groups=[('Actual Android taps and saved claim',['Device/Tap_READY_HOME_TAP.png','Device/Tap/Daily_Ready.png','Device/Tap/Daily_Claimed.png','Device/Restart/Daily_Restart_Claimed.png']),('Approved provisional seven-day track',[f'Device/Auto/Daily_Day{i}.png' for i in range(1,8)]),('Five language layouts',[f'Device/Auto/Daily_Locale_{code}.png' for code in ['en','es','fr','de','ru']]),('Unavailable and recovery states',['Device/Auto/Daily_Offline.png','Device/Auto/Daily_Pending_Retry.png','Device/Auto/Tool_Save_Recovery.png']),('Durable gameplay and Home flow',['Device/StartAttempt/Gameplay_Before_ForceStop.png','Device/Recover/Home_Interrupted_Recover.png','Device/RecoverAgain/Home_Interrupted_RecoverAgain.png','Device/Auto/Connected_Win_Celebration.png','Device/Auto/Home_After_Win.png','Device/WonRestart/Home_Won_Restart.png']),('Additional portrait sizes',['Compact/Restart/Daily_Restart_Claimed.png','Tablet/Restart/Daily_Restart_Claimed.png'])]
    for title,names in groups:
        cards=[]
        for name in names:
            if (OUT/name).exists():cards.append(f'<figure><a href="{html.escape(name)}"><img loading="lazy" src="{html.escape(name)}" alt="{html.escape(Path(name).stem)}"></a><figcaption>{html.escape(Path(name).stem.replace("_"," "))}</figcaption></figure>')
        if cards:sections.append(f'<section><h2>{html.escape(title)}</h2><div class="gallery">'+''.join(cards)+'</div></section>')
    status='Captured evidence; visual review pending.'
    if (OUT/'Visual_Review.json').exists():status=json.loads((OUT/'Visual_Review.json').read_text())['status']
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Heart of the Rain — Daily Gift review</title><style>body{margin:0;background:#f5f0e5;color:#17354e;font:16px/1.55 system-ui}main{max-width:1440px;margin:auto;padding:28px}h1{font-size:30px}h2{font-size:23px;margin-top:32px}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}figure{margin:0;padding:10px;background:white;border:1px solid #c5cbd0;border-radius:8px}img{display:block;max-width:100%;max-height:690px;margin:auto}figcaption{font-size:13px;padding:9px 0;overflow-wrap:anywhere}code{overflow-wrap:anywhere}a{color:#00695c}.note{border-left:4px solid #b88d3a;padding:12px 18px;background:white}table{border-collapse:collapse;background:white}td,th{border:1px solid #ccd1d4;padding:8px;text-align:left}</style><main><h1>Daily Gift · development review</h1><p>Original native LDPlayer captures. Click an image for full resolution. Existing artwork and palette are reused; this is one component for owner review.</p><p class="note">The authority is a LOCAL development simulation, labelled Preview rewards. Production claiming is unavailable until a real authenticated service is connected. Wellworks and Rain Cup remain demonstration content.</p><p><strong>Visual evidence:</strong> STATUS</p><p><strong>APK SHA-256:</strong> <code>DIGEST</code></p><table><tr><th>Day</th><th>Provisional reward</th></tr><tr><td>1</td><td>50 coins</td></tr><tr><td>2</td><td>1 Rocket</td></tr><tr><td>3</td><td>75 coins</td></tr><tr><td>4</td><td>1 Bomb</td></tr><tr><td>5</td><td>100 coins</td></tr><tr><td>6</td><td>1 Hammer</td></tr><tr><td>7</td><td>150 coins + 1 Orb</td></tr></table><p>One gift per authority day; missed days retain the next gift. Started unfinished attempts settle as one loss on reopening, once; used items stay spent. Failed initialization costs nothing. Win rewards are saved before celebration; Home remains the return destination.</p>SECTIONS<p>Life regeneration, exact board resume, real server time/account recovery, physical-device certification and final economy/native-language review remain open. Isolated verification saves leave the ordinary player profile and settings unchanged.</p><p><a href="Verification_Summary.json">Verification summary</a> · <a href="../../../Codex_Handoff/Documentation/27_DAILY_GIFT_AND_DURABLE_PROFILE_REVIEW.md">Implementation and remaining limits</a></p></main></html>'''
    (OUT/'Comparison.html').write_text(template.replace('DIGEST',manifest['apk_sha256']).replace('STATUS',html.escape(status)).replace('SECTIONS',''.join(sections)),encoding='utf-8')
    print('Built',OUT/'Comparison.html')
if __name__=='__main__':run()
